-- Origin (spec 003 task 01, decision 0003): where a Check, event or Feature Request came from.
-- Generated by drizzle-kit, then edited: columns are added nullable, backfilled, then made NOT NULL.
--
-- Backfill rule for rows written before Origin existed (all in the Crewday Demo Workspace):
--   checks           'eval' when written by the eval runner (actor "eval", type agent: the only actor
--                    evals/signal-verdict/run.ts uses); otherwise 'demo'. Seeding never wrote Checks.
--   feature_requests 'seed' when the seed wrote it (seed_key is set); otherwise the Origin of the
--                    Check that created it (check_id); otherwise 'demo'.
--   events           the Origin of the Check named in payload.checkId, when there is one; otherwise
--                    'demo'. Seeding never wrote events; review events came from the demo caller.
ALTER TABLE "checks" ADD COLUMN "origin" text;--> statement-breakpoint
ALTER TABLE "events" ADD COLUMN "origin" text;--> statement-breakpoint
ALTER TABLE "feature_requests" ADD COLUMN "origin" text;--> statement-breakpoint
UPDATE "checks" SET "origin" = CASE
	WHEN "actor_name" = 'eval' AND "actor_type" = 'agent' THEN 'eval'
	ELSE 'demo'
END;--> statement-breakpoint
UPDATE "feature_requests" SET "origin" = COALESCE(
	CASE WHEN "seed_key" IS NOT NULL THEN 'seed' END,
	(SELECT "checks"."origin" FROM "checks" WHERE "checks"."id" = "feature_requests"."check_id"),
	'demo'
);--> statement-breakpoint
UPDATE "events" SET "origin" = COALESCE(
	(SELECT "checks"."origin" FROM "checks" WHERE "checks"."id"::text = "events"."payload"->>'checkId'),
	'demo'
);--> statement-breakpoint
ALTER TABLE "checks" ALTER COLUMN "origin" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "events" ALTER COLUMN "origin" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "feature_requests" ALTER COLUMN "origin" SET NOT NULL;--> statement-breakpoint
CREATE INDEX "events_workspace_origin_type" ON "events" USING btree ("workspace_id","origin","type");--> statement-breakpoint
CREATE INDEX "feature_requests_workspace_origin" ON "feature_requests" USING btree ("workspace_id","origin");--> statement-breakpoint
ALTER TABLE "checks" ADD CONSTRAINT "checks_origin" CHECK ("checks"."origin" in ('pilot', 'demo', 'seed', 'eval'));--> statement-breakpoint
ALTER TABLE "events" ADD CONSTRAINT "events_origin" CHECK ("events"."origin" in ('pilot', 'demo', 'seed', 'eval'));--> statement-breakpoint
ALTER TABLE "feature_requests" ADD CONSTRAINT "feature_requests_origin" CHECK ("feature_requests"."origin" in ('pilot', 'demo', 'seed', 'eval'));
